	SELECT
	    workers.id,
	    CONCAT_WS(' ', workers.username, workers.username2, workers.surname, workers.surname2, workers.surname3) AS userFullName,
	    jobpositions.jobpos_name,
	    checkins.checktime,
	    'worker' AS type
	FROM checkins
	JOIN workers ON checkins.workerid = workers.id
	JOIN jobpositions ON workers.jobpos_id = jobpositions.id
	UNION ALL
	SELECT
	    administrators.id,
	    CONCAT_WS(' ', administrators.username, administrators.username2, administrators.surname, administrators.surname2, administrators.surname3) AS userFullName,
	    jobpositions.jobpos_name,
	    checkins.checktime,
	    'admin' AS type
	FROM checkins
	JOIN administrators ON checkins.adminid = administrators.id
	JOIN jobpositions ON administrators.jobpos_id = jobpositions.id
	ORDER BY checktime ASC;

